          example_reasoning: name + '：推测过程尚未记录。', source_unknown: name.replace(/ \/ (condition|mapping|boundary)$/, (_, key) => ' · ' + ({ condition: '适用条件', mapping: '映射规律', boundary: '边界' }[key])) + '：来源身份尚未核对。',
